/* Transit selection uses the first available fourfold or sixfold level, never a union. */
(()=>{'use strict';function firstAvailable(row,method="fourfold"){for(const level of (method==='sixfold'?['A','B','C','D','E','F']:['A','B','C','D'])){const houses=[...new Set((Array.isArray(row?.[level])?row[level]:[]).filter(h=>Number.isInteger(h)&&h>=1&&h<=12))].sort((a,b)=>a-b);if(houses.length)return {level,houses};}return {level:null,houses:[]};}function select(model,required,method="fourfold"){const wanted=new Set(required);return (model?.[method==='sixfold'?'sixfold':'fourfold']?.planets||[]).map(row=>{const chosen=firstAvailable(row,method),matched=chosen.houses.filter(h=>wanted.has(h));return {id:row.id,level:chosen.level,sourceHouses:chosen.houses,houses:matched};}).filter(row=>row.houses.length);}
window.KPTransitSignificators=Object.freeze({firstAvailable,select});})();
